const express = require('express');
const { DocumentShare, ConfidentialDocument } = require('../models');
const { auth } = require('../auth');

const app = express();

DocumentShare.addHook('afterFind', async (instance) => {
  if (instance && instance.documentId) {
    const doc = await ConfidentialDocument.findByPk(instance.documentId);
    instance.setDataValue('document', doc);
  }
});

app.get('/api/shares/:shareId', auth, async (req, res) => {
  const { shareId } = req.params;

  // Verify that the authenticated user is the designated recipient or creator of the share
  const share = await DocumentShare.findOne({
    where: {
      id: shareId,
      recipientEmail: req.user.email
    }
  });

  if (!share) {
    return res.status(404).json({ error: 'Share link not found or access denied' });
  }

  res.json({ share });
});

app.listen(8108);
